{
  "justification": "Immigration, law and order, and terrorism dominate salience, indicating strong concerns about group boundaries, security, and social order, while the NHS’s prominence and a slight tilt toward higher public spending signal care and equality motives. The low authoritarian placement (2.35/10 on crime vs rights) and middling EU position temper pure authority/loyalty emphasis, spreading weight to proportionality and sanctity where these issues are contested in both directions.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "High salience of NHS (14.2%) and some focus on poverty/living standards (1.1%) and services-spending (2.0%).",
      "weight": 0.22
    },
    {
      "foundation": "loyalty",
      "basis": "Top concern with Immigration (19.0%), attention to Terrorism (5.8%), and EU integration midpoint (5.16) reflecting nation/coalition boundaries.",
      "weight": 0.20
    },
    {
      "foundation": "authority",
      "basis": "Law & order-crime salience (13.2%) and terrorism (5.8%) offset by liberal social position 2.35/10 on crime vs rights.",
      "weight": 0.15
    },
    {
      "foundation": "sanctity",
      "basis": "Immigration and Asylum (19.0%/4.8%) plus environment (1.8%) and drugs (0.5%) cue purity/contamination and elevation narratives.",
      "weight": 0.12
    },
    {
      "foundation": "equality",
      "basis": "Economic position leans toward more public spending (5.54/10) and strong NHS salience (14.2%).",
      "weight": 0.18
    },
    {
      "foundation": "proportionality",
      "basis": "Taxation (3.6%), economy (4.4%), welfare fraud (0.1%), and crime salience (13.2%) reflect merit, reciprocity, and deservedness concerns.",
      "weight": 0.13
    }
  ]
}
